// PATTERN 1: OPPOSITE ENDS — Two Sum on sorted array
// Naive: O(n^2) nested loops checking every pair
// Two Pointer: O(n) time, O(1) space
function twoSumSorted(nums, target) {
    let left = 0, right = nums.length - 1;
    while (left < right) {
        const sum = nums[left] + nums[right];
        if (sum === target) return [left, right]; // found
        if (sum < target) left++;   // sum too small: move left pointer right
        else right--;               // sum too big:  move right pointer left
    }
    return [];
}
// [1,2,3,4,6], target=6 -> left=0(1), right=4(6): sum=7>6 -> right--
//                          left=0(1), right=3(4): sum=5<6 -> left++
//                          left=1(2), right=3(4): sum=6 == target -> [1,3]

// PATTERN 2: OPPOSITE ENDS — Valid Palindrome
function isPalindrome(s) {
    // Clean: keep only alphanumeric, lowercase
    s = s.toLowerCase().replace(/[^a-z0-9]/g, '');
    let left = 0, right = s.length - 1;
    while (left < right) {
        if (s[left] !== s[right]) return false;
        left++;
        right--;
    }
    return true;
}
// Time: O(n)  Space: O(n) for cleaned string
// Space-optimised: skip non-alphanumeric in-place without creating new string -> O(1) space

// PATTERN 3: SAME DIRECTION — Remove Duplicates In-Place (sorted array)
// slow pointer: position of last unique element written
// fast pointer: scanning ahead for new unique elements
function removeDuplicates(nums) {
    if (nums.length === 0) return 0;
    let slow = 0;
    for (let fast = 1; fast < nums.length; fast++) {
        if (nums[fast] !== nums[slow]) {
            slow++;
            nums[slow] = nums[fast]; // write new unique value
        }
        // if equal: fast advances, slow stays — effectively skipping duplicate
    }
    return slow + 1; // length of deduplicated prefix
}
// [0,0,1,1,1,2,2,3]: slow writes unique values in-place
// Result: [0,1,2,3,...] with slow+1 = 4 unique elements
// Time: O(n)  Space: O(1)

// FIXED-SIZE WINDOW: Maximum sum of subarray of size k
function maxSumSubarray(nums, k) {
    // Build first window
    let windowSum = 0;
    for (let i = 0; i < k; i++) windowSum += nums[i];
    let maxSum = windowSum;

    // Slide: add right element, remove left element
    for (let right = k; right < nums.length; right++) {
        windowSum += nums[right];        // expand: new element enters
        windowSum -= nums[right - k];    // shrink: old element leaves
        maxSum = Math.max(maxSum, windowSum);
    }
    return maxSum;
}
// [2,1,5,1,3,2], k=3 -> windows: [2,1,5]=8, [1,5,1]=7, [5,1,3]=9, [1,3,2]=6 -> 9
// Time: O(n)  Space: O(1)

// VARIABLE-SIZE WINDOW: Longest substring without repeating characters
function lengthOfLongestSubstring(s) {
    const charSet = new Set(); // tracks characters in current window
    let left = 0;
    let maxLen = 0;

    for (let right = 0; right < s.length; right++) {
        // Shrink window from left until no duplicate
        while (charSet.has(s[right])) {
            charSet.delete(s[left]); // remove leftmost char
            left++;                   // shrink window
        }
        charSet.add(s[right]);        // expand: add new char
        maxLen = Math.max(maxLen, right - left + 1);
    }
    return maxLen;
}
// 'abcabcbb': right scans forward, left shrinks when duplicate found
// 'abc' -> 'a' enters again -> shrink left past 'a' -> 'bca' -> ... -> maxLen=3
// Time: O(n)  Space: O(min(n, alphabet_size))

// RECOGNITION SIGNAL:
// 'subarray/substring of size k'      -> fixed window
// 'longest/shortest satisfying X'      -> variable window
// 'contiguous elements'                -> sliding window candidate

// BUILDING A PREFIX SUM ARRAY
function buildPrefix(arr) {
    const prefix = new Array(arr.length + 1).fill(0); // dummy 0 at index 0
    for (let i = 0; i < arr.length; i++) {
        prefix[i + 1] = prefix[i] + arr[i];
    }
    return prefix;
}
// arr =    [3, 1, 4, 1, 5, 9, 2, 6]
// prefix = [0, 3, 4, 8, 9, 14,23,25,31]
//           ^dummy

// RANGE SUM QUERY: O(1) after O(n) build
function rangeSum(prefix, l, r) {
    return prefix[r + 1] - prefix[l]; // sum of arr[l..r] inclusive
}
// Sum of arr[2..5] = prefix[6] - prefix[2] = 23 - 4 = 19
// Verify: arr[2]+arr[3]+arr[4]+arr[5] = 4+1+5+9 = 19 ✓

// WITHOUT PREFIX: k queries each O(n) -> O(n*k) total
// WITH PREFIX:    O(n) build + k * O(1) queries -> O(n + k) total

// APPLICATION: Subarray Sum Equals K (LeetCode #560)
// Count subarrays summing to k
function subarraySum(nums, k) {
    const countMap = new Map([[0, 1]]); // prefix sum 0 seen once (empty subarray)
    let prefixSum = 0;
    let count = 0;
    for (const num of nums) {
        prefixSum += num;
        // If (prefixSum - k) was seen before, those subarrays sum to k
        count += countMap.get(prefixSum - k) || 0;
        countMap.set(prefixSum, (countMap.get(prefixSum) || 0) + 1);
    }
    return count;
}
// Time: O(n)  Space: O(n)
// This combines prefix sums with a hash map — a Level 2 pattern preview

// STRING IMMUTABILITY — concatenation in a loop: O(n^2)
function buildString_slow(chars) {
    let result = '';
    for (const c of chars) result += c; // NEW string allocated each iteration
    return result;
}
// n iterations, iteration i copies i characters: total copies = n(n+1)/2 = O(n^2)

// CORRECT PATTERN — array join: O(n)
function buildString_fast(chars) {
    const parts = [];
    for (const c of chars) parts.push(c); // O(1) amortized each
    return parts.join('');                  // one O(n) pass
}

// CHARACTER MAP — frequency count in O(n)
function charFrequency(s) {
    const freq = {};
    for (const c of s) freq[c] = (freq[c] || 0) + 1;
    return freq;
}
// 'hello' -> { h:1, e:1, l:2, o:1 }

// STRING REVERSAL — two pointer on array copy
function reverseString(s) {
    const arr = s.split('');   // O(n) copy (unavoidable: strings immutable)
    let left = 0, right = arr.length - 1;
    while (left < right) {
        [arr[left], arr[right]] = [arr[right], arr[left]]; // swap
        left++; right--;
    }
    return arr.join('');
}
// Time: O(n)  Space: O(n) [copy required due to immutability]

// ASCII ARITHMETIC — useful for letter counting without objects
function countLetters(s) {
    const count = new Array(26).fill(0); // index 0='a', 25='z'
    for (const c of s.toLowerCase()) {
        if (c >= 'a' && c <= 'z') {
            count[c.charCodeAt(0) - 97]++; // 'a'=97
        }
    }
    return count;
}
// Space: O(1) — fixed 26-element array regardless of string length

// VALID ANAGRAM: O(n) time, O(1) space (fixed alphabet)
function isAnagram(s, t) {
    if (s.length !== t.length) return false;
    const count = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {
        count[s.charCodeAt(i) - 97]++; // increment for s
        count[t.charCodeAt(i) - 97]--; // decrement for t
    }
    return count.every(c => c === 0); // all zeros = same frequencies
}

// GROUP ANAGRAMS: O(n * k log k) where k = average string length
function groupAnagrams(strs) {
    const map = new Map();
    for (const s of strs) {
        const key = s.split('').sort().join(''); // sorted string as key
        if (!map.has(key)) map.set(key, []);
        map.get(key).push(s);
    }
    return [...map.values()];
}
// ['eat','tea','tan','ate','nat','bat']
// 'eat'->'aet', 'tea'->'aet', 'ate'->'aet' all map to same key
// Result: [['eat','tea','ate'],['tan','nat'],['bat']]

// FIND ALL ANAGRAMS IN STRING: Sliding Window + Frequency Map O(n)
function findAnagrams(s, p) {
    if (s.length < p.length) return [];
    const pCount = new Array(26).fill(0);
    const wCount = new Array(26).fill(0);
    for (let i = 0; i < p.length; i++) {
        pCount[p.charCodeAt(i) - 97]++;
        wCount[s.charCodeAt(i) - 97]++;
    }
    const result = [];
    if (pCount.join() === wCount.join()) result.push(0);

    for (let right = p.length; right < s.length; right++) {
        wCount[s.charCodeAt(right) - 97]++;           // add new right char
        wCount[s.charCodeAt(right - p.length) - 97]--; // remove old left char
        if (pCount.join() === wCount.join()) result.push(right - p.length + 1);
    }
    return result;
}
// Time: O(n)  Space: O(1) — fixed 26-element arrays

// KADANE'S ALGORITHM: Maximum Subarray Sum O(n)
function maxSubArray(nums) {
    let currentSum = nums[0];
    let maxSum = nums[0];
    for (let i = 1; i < nums.length; i++) {
        // Extend current subarray or start fresh at nums[i]
        currentSum = Math.max(nums[i], currentSum + nums[i]);
        maxSum = Math.max(maxSum, currentSum);
    }
    return maxSum;
}
// [-2,1,-3,4,-1,2,1,-5,4]
// currentSum: -2, 1, -2, 4, 3, 5, 6, 1, 5
// maxSum:     -2, 1,  1, 4, 4, 5, 6, 6, 6  -> answer: 6 (subarray [4,-1,2,1])
// Time: O(n)  Space: O(1)

// MAXIMUM PRODUCT SUBARRAY O(n)
// Key insight: negative * negative = positive, so track both max and min
function maxProduct(nums) {
    let maxProd = nums[0], minProd = nums[0], result = nums[0];
    for (let i = 1; i < nums.length; i++) {
        const num = nums[i];
        const candidates = [num, maxProd * num, minProd * num];
        maxProd = Math.max(...candidates);
        minProd = Math.min(...candidates);
        result = Math.max(result, maxProd);
    }
    return result;
}
// [2,3,-2,4]: maxProd:2,6,-2,? minProd:2,3,-12,? -> 6
// [-2,3,-4]: min tracks -12, max = -12 * -4 = 48? -> 24... trace carefully

// PATTERN SELECTION GUIDE:
// Max subarray SUM (can be negative)    -> Kadane's O(n)
// Subarray sum EQUALS k (any integers)  -> prefix sum + hashmap O(n)
// Min SIZE with sum >= target (positive) -> sliding window O(n)
// Max subarray PRODUCT                   -> track max+min O(n)

// FOUR-DIRECTIONAL TRAVERSAL (foundation for DFS/BFS on grids — Module 10)
const DIRS = [[0,1],[0,-1],[1,0],[-1,0]]; // right, left, down, up

function getNeighbours(matrix, row, col) {
    const m = matrix.length, n = matrix[0].length;
    const neighbours = [];
    for (const [dr, dc] of DIRS) {
        const r = row + dr, c = col + dc;
        if (r >= 0 && r < m && c >= 0 && c < n) { // bounds check
            neighbours.push([r, c]);
        }
    }
    return neighbours;
}

// SPIRAL ORDER TRAVERSAL
function spiralOrder(matrix) {
    const result = [];
    let top = 0, bottom = matrix.length - 1;
    let left = 0, right = matrix[0].length - 1;

    while (top <= bottom && left <= right) {
        for (let c = left; c <= right; c++) result.push(matrix[top][c]);   // top row
        top++;
        for (let r = top; r <= bottom; r++) result.push(matrix[r][right]); // right col
        right--;
        if (top <= bottom)
            for (let c = right; c >= left; c--) result.push(matrix[bottom][c]); // bottom row
        bottom--;
        if (left <= right)
            for (let r = bottom; r >= top; r--) result.push(matrix[r][left]);   // left col
        left++;
    }
    return result;
}

// IN-PLACE 90-DEGREE ROTATION (transpose then reverse rows)
function rotate(matrix) {
    const n = matrix.length;
    // Step 1: Transpose — swap matrix[i][j] with matrix[j][i]
    for (let i = 0; i < n; i++)
        for (let j = i + 1; j < n; j++)
            [matrix[i][j], matrix[j][i]] = [matrix[j][i], matrix[i][j]];
    // Step 2: Reverse each row
    for (let i = 0; i < n; i++)
        matrix[i].reverse();
}
// Time: O(n^2)  Space: O(1) in-place

